import axios from 'axios'
const blockList = ['']

exports.validateToken = (req, jwt, secret) => {
  const authorization = req.headers['authorization']
  if (!authorization) throw new Error('Token invalido')
  const bearer = authorization.split(' ')
  if (bearer.length < 2) throw new Error('Token invalido')
  const token = bearer[1]
  if (blockList.some(d => d === token)) throw new Error('Token invalido')
  const data = jwt.verify(token, secret)
  if (!data) throw new Error('Error en data de Token')
  return data
}

exports.validateEmail = (email) => {
  var re = /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
  return re.test(String(email).toLowerCase())
}

exports.getUsers = async (req) => {
  let users = await req.app.db.models.user.find({}, {
    username: 1,
    first_name: 1,
    last_name: 1,
    email: 1,
    phone: 1
  })
  return users
}

exports.getImagesDestination = async (query) => {
  const key = '26002882-1fdd9a2de0ebd7200f8afca36'
  let images = []
  let objectImages = []
  let result = []
  try {
    let resultImages = await axios.get(`https://pixabay.com/api/?key=${key}&q=${encodeURIComponent(query)}&image_type=photo&per_page=6`)
    for (const image of resultImages.data.hits) {
      if (objectImages.length === 0 || !objectImages.includes(image.tags)) {
        objectImages.push(image.tags)
        images.push(image.largeImageURL)
      }
    }
    if (images.length) {
      for (const url of images.slice(0, 3)) {
        let response = await axios.get(url, { responseType: 'arraybuffer' })
        let buffer = Buffer.from(response.data).toString('base64')
        result.push(buffer)
      }
    }

    return result
  } catch (error) {
    console.log(error)
    return null
  }
}

